package com.familya.sharing.adapter.out.persistence; import org.springframework.jdbc.core.namedparam.NamedParameterJdbcTemplate; import org.springframework.stereotype.Component; import java.time.*; import java.util.*; @Component public class JdbcWatermarkRepository {private final NamedParameterJdbcTemplate jdbc;public JdbcWatermarkRepository(NamedParameterJdbcTemplate j){jdbc=j;}public long watermark(UUID tree){var x=jdbc.queryForList("SELECT MAX(watermark) w FROM share_allowlisted_projection WHERE tree_id=:t",Map.of("t",tree.toString()));return x.isEmpty()||x.get(0).get("w")==null?0:((Number)x.get(0).get("w")).longValue();}}
